"""LangChain integration — StrataRetriever and StrataChatMemory.

Install: pip install strata-memory[langchain]
"""

from __future__ import annotations

from typing import Any

try:
    from langchain_core.callbacks import CallbackManagerForRetrieverRun
    from langchain_core.chat_history import BaseChatMessageHistory
    from langchain_core.documents import Document
    from langchain_core.messages import AIMessage, BaseMessage, HumanMessage
    from langchain_core.retrievers import BaseRetriever
except ImportError as exc:
    raise ImportError(
        "LangChain integration requires langchain-core. "
        "Install with: pip install strata-memory[langchain]"
    ) from exc

from strata.async_client import AsyncStrataClient
from strata.client import StrataClient


class StrataRetriever(BaseRetriever):
    """LangChain retriever backed by Strata memory search.

    Usage::

        from strata import StrataClient
        from strata.integrations.langchain import StrataRetriever

        s = StrataClient()
        retriever = StrataRetriever(client=s, search_kwargs={"limit": 5})
        docs = retriever.invoke("auth patterns")
    """

    client: Any  # StrataClient — Any to avoid pydantic validation issues
    search_kwargs: dict[str, Any] = {}

    class Config:
        arbitrary_types_allowed = True

    def _get_relevant_documents(
        self,
        query: str,
        *,
        run_manager: CallbackManagerForRetrieverRun | None = None,
    ) -> list[Document]:
        results = self.client.search(query, **self.search_kwargs)
        return [
            Document(
                page_content=r.text,
                metadata={
                    "score": r.score,
                    "project": r.project or "",
                    "date": r.date or "",
                    "source": "strata",
                },
            )
            for r in results
        ]


class StrataChatMemory(BaseChatMessageHistory):
    """LangChain chat memory backed by Strata conversation ingestion.

    Stores conversation turns and retrieves relevant history.

    Usage::

        from strata import StrataClient
        from strata.integrations.langchain import StrataChatMemory

        s = StrataClient()
        memory = StrataChatMemory(client=s, project="my-agent")
    """

    def __init__(
        self,
        client: StrataClient | AsyncStrataClient,
        *,
        project: str | None = None,
        user: str | None = None,
        session_id: str | None = None,
    ) -> None:
        self._client = client
        self._project = project
        self._user = user
        self._session_id = session_id
        self._messages: list[BaseMessage] = []

    @property
    def messages(self) -> list[BaseMessage]:
        """Return message history."""
        return self._messages

    def add_message(self, message: BaseMessage) -> None:
        """Add a message to the store."""
        self._messages.append(message)

    def add_user_message(self, message: str) -> None:
        """Add a user message."""
        self.add_message(HumanMessage(content=message))

    def add_ai_message(self, message: str) -> None:
        """Add an AI message and persist the exchange to Strata."""
        self.add_message(AIMessage(content=message))
        # Persist the last exchange
        if len(self._messages) >= 2:
            recent = self._messages[-2:]
            msgs = [
                {
                    "role": "user" if isinstance(m, HumanMessage) else "assistant",
                    "text": str(m.content),
                }
                for m in recent
            ]
            if isinstance(self._client, StrataClient):
                self._client.ingest(
                    msgs, agent="langchain", project=self._project or "default"
                )

    def clear(self) -> None:
        """Clear message history."""
        self._messages = []
